<script setup>
import { ref, reactive, computed, onMounted, onUnmounted, nextTick } from 'vue';
import { Database, LayoutDashboard, CalendarClock, History, Settings, ShieldCheck, LogOut, ArrowUpRight, ArrowRight, Plus, RefreshCw, Play, Download, X, Clock3, HardDrive, CircleCheck, TriangleAlert, ChevronRight, LockKeyhole, Server, Search, Menu, Lightbulb, Wrench } from 'lucide-vue-next';
const user=ref(null),booting=ref(true),loading=ref(false),busy=ref(false),page=ref('overview'),toast=ref(''),error=ref(''),modal=ref(null),search=ref(''),mobileNav=ref(false);
const data=reactive({databases:[],schedules:[],runs:[],settings:{},stats:{}});
const login=reactive({email:'',password:''});
const dbForm=ref({}),scheduleForm=ref({});
const options=reactive({retention_count:4,timeout_minutes:360,minimum_free_gb:1,external_copy:false});
let csrf=document.querySelector('meta[name="csrf-token"]').content,timer,toastTimer;
const days=[{n:1,s:'Seg',name:'Segunda'},{n:2,s:'Ter',name:'Terça'},{n:3,s:'Qua',name:'Quarta'},{n:4,s:'Qui',name:'Quinta'},{n:5,s:'Sex',name:'Sexta'},{n:6,s:'Sáb',name:'Sábado'},{n:7,s:'Dom',name:'Domingo'}];
const nav=[{key:'overview',name:'Visão geral',icon:LayoutDashboard},{key:'databases',name:'Bancos de dados',icon:Database},{key:'schedules',name:'Agendamentos',icon:CalendarClock},{key:'history',name:'Histórico',icon:History},{key:'settings',name:'Configurações',icon:Settings}];
const drivers={mysql:{name:'MySQL',port:3306},pgsql:{name:'PostgreSQL',port:5432},sqlite:{name:'SQLite',port:22}};
const status={queued:'Na fila',running:'Em execução',success:'Concluído',failed:'Falhou',expired:'Expirado',cancelled:'Cancelado'};
const title=computed(()=>nav.find(n=>n.key===page.value)?.name);
const filteredRuns=computed(()=>data.runs.filter(r=>`${r.id} ${r.database_server?.name} ${status[r.status]}`.toLowerCase().includes(search.value.toLowerCase())));
const failedAge=computed(()=>!data.settings.worker_heartbeat || Date.now()-parseDate(data.settings.worker_heartbeat).getTime()>120000);
const available=computed(()=>data.runs.filter(r=>r.status==='success').reduce((n,r)=>n+(r.size_bytes||0),0));
const activeSchedules=computed(()=>data.schedules.filter(s=>s.enabled && s.database_server?.enabled));
function parseDate(value){return new Date(value && !value.includes('T') ? value.replace(' ','T')+'Z' : value);}
function date(value){return value?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Cuiaba'}).format(parseDate(value)):'—';}
function bytes(n){if(!n)return '—';if(n<1048576)return (n/1024).toLocaleString('pt-BR',{maximumFractionDigits:1})+' KB';if(n<1073741824)return (n/1048576).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MB';return (n/1073741824).toLocaleString('pt-BR',{maximumFractionDigits:2})+' GB';}
function dayLabels(s){return days.filter(d=>s.weekdays.includes(d.n)).map(d=>d.s).join(' · ');}
function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',7000);}
async function api(path,method='GET',body=null,retried=false){
 const response=await fetch('/api'+path,{method,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:body?JSON.stringify(body):undefined});
 const result=await response.json().catch(()=>({message:'Resposta inválida do servidor.'}));
 if(response.status===419 && !retried){const token=await fetch('/api/csrf',{headers:{Accept:'application/json'}}).then(r=>r.json());csrf=token.csrf;return api(path,method,body,true);}
 if(!response.ok){if(response.status===401)user.value=null;throw new Error(result.errors?Object.values(result.errors).flat().join(' '):(result.message||'Não foi possível concluir a ação.'));}
 if(result.csrf)csrf=result.csrf;return result;
}
async function load(silent=false){if(!user.value)return;if(!silent)loading.value=true;try{Object.assign(data,await api('/overview'));if(page.value!=='settings')Object.assign(options,data.settings);}catch(e){if(!silent)error.value=e.message;}finally{loading.value=false;}}
async function signIn(){busy.value=true;error.value='';try{const r=await api('/login','POST',login);user.value=r.user;login.password='';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function signOut(){try{await api('/logout','POST');user.value=null;page.value='overview';}catch(e){error.value=e.message;}}
function navigate(key){page.value=key;hl.value=[];error.value='';mobileNav.value=false;if(key==='settings')Object.assign(options,data.settings);}
const hl=ref([]),fixHint=ref(null);
// Dicas para erros conhecidos: o que aconteceu, o que fazer e onde. where: tela a abrir; fields: campos destacados.
const hints=[
 {m:["ssl is required but the server doesn't support it",'server does not support ssl'],title:'O servidor não aceita conexão criptografada (TLS).',steps:['Abra a configuração do banco.','Em "Conexão TLS", escolha "Sem TLS / túnel externo".','Salve e gere um novo backup de teste.'],where:'database',fields:['tls_mode']},
 {m:['certificate verify failed','ssl connection error','ssl error','certificate'],title:'Falha na verificação do certificado TLS.',steps:['Abra a configuração do banco.','Em "Conexão TLS", use "Exigir TLS" em vez de "TLS + validar identidade", ou informe o "Arquivo CA" correto (o arquivo deve estar na pasta certs/).','Se o servidor não usa TLS, escolha "Sem TLS / túnel externo".'],where:'database',fields:['tls_mode','ca_file']},
 {m:['access denied for user','password authentication failed','authentication failed'],title:'Usuário ou senha recusados pelo banco.',steps:['Abra a configuração do banco e confira "Usuário" e "Senha" (digite a senha novamente).','Confirme no painel da hospedagem se o usuário tem acesso a este banco.','Se usuário e senha estiverem certos, libere o IP deste servidor em "Acesso remoto ao MySQL" na hospedagem.'],where:'database',fields:['username','db_password']},
 {m:['unknown database','does not exist','banco vazio, inexistente'],title:'Banco de dados não encontrado ou sem permissão para ler as tabelas.',steps:['Abra a configuração do banco.','Confira o campo "Banco de dados": o nome deve ser exatamente o do servidor (maiúsculas e minúsculas importam).','Confirme na hospedagem se o usuário tem permissão neste banco.'],where:'database',fields:['database_name','username']},
 {m:["unknown mysql server host",'could not translate host name','name or service not known','temporary failure in name resolution'],title:'O endereço do servidor (host) não foi encontrado.',steps:['Abra a configuração do banco.','Confira o campo "Host" (ex.: mysql.seudominio.com.br), sem http:// e sem espaços.'],where:'database',fields:['host']},
 {m:["can't connect to mysql server",'connection refused','connection timed out','timeout expired','could not connect','lost connection to mysql server at \'reading initial'],title:'Não foi possível conectar no servidor do banco.',steps:['Abra a configuração do banco e confira "Host" e "Porta" (MySQL usa 3306, PostgreSQL 5432).','Na hospedagem, libere o acesso remoto ao banco para o IP deste servidor.','Verifique se o servidor do banco está no ar.'],where:'database',fields:['host','port']},
 {m:['motores não transacionais'],title:'O banco tem tabelas MyISAM, que não podem ser copiadas em modo transação.',steps:['Abra a configuração do banco.','Em "Consistência do backup", escolha "Bloqueio das tabelas do banco (MyISAM)".','Salve e gere um novo backup de teste, de preferência fora do horário de uso.'],where:'database',fields:['consistency']},
 {m:['reload privilege','flush tables','super privilege'],title:'O usuário não tem permissão para o bloqueio global.',steps:['Abra a configuração do banco.','Em "Consistência do backup", troque para "Bloqueio das tabelas do banco (MyISAM)".'],where:'database',fields:['consistency']},
 {m:['lock tables'],title:'O usuário não tem permissão para bloquear as tabelas durante o backup.',steps:['Peça à hospedagem para liberar a permissão LOCK TABLES para este usuário.','Se todas as tabelas forem InnoDB, use "Transação InnoDB" em "Consistência do backup".'],where:'database',fields:['consistency']},
 {m:['server version mismatch'],title:'A versão do PostgreSQL do servidor é mais nova que o cliente de backup.',steps:['O administrador precisa atualizar o cliente pg_dump no Dockerfile (pacote postgresql-client) para a mesma versão do servidor.'],where:null,fields:[]},
 {m:['arquivo sqlite não encontrado','caminho remoto do sqlite inválido','nome de arquivo sqlite inválido'],title:'Arquivo SQLite não encontrado.',steps:['Abra a configuração do banco.','Sem host: coloque o arquivo na pasta sqlite/ do projeto e informe só o nome (ex.: sistema.sqlite).','Com host SSH: informe o caminho completo no servidor (ex.: /home/usuario/app/database.sqlite).'],where:'database',fields:['database_name','host']},
 {m:['usuário ou senha ssh recusados'],title:'O servidor SSH recusou o usuário ou a senha.',steps:['Abra a configuração do banco e confira "Usuário SSH" e "Senha SSH".','Confira a "Porta" do SSH (normalmente 22).'],where:'database',fields:['username','db_password','port']},
 {m:['chave ssh do servidor mudou'],title:'A identidade (chave SSH) do servidor mudou.',steps:['Confirme com a hospedagem se o servidor foi trocado.','Se for legítimo, o administrador remove a linha do host em /data/keys/ssh_known_hosts e gera um novo backup.'],where:null,fields:[]},
 {m:['certificado ca não encontrado','certificado inválido'],title:'Arquivo de certificado CA não encontrado.',steps:['Coloque o arquivo .pem na pasta certs/ do projeto.','Na configuração do banco, informe só o nome do arquivo em "Arquivo CA", ou deixe vazio.'],where:'database',fields:['ca_file']},
 {m:['tempo limite','timeout'],title:'O backup demorou mais que o tempo máximo configurado.',steps:['Abra Configurações.','Aumente "Tempo máximo do dump (minutos)" e salve.'],where:'settings',fields:['timeout_minutes']},
 {m:['reserva mínima','espaço em disco','espaço insuficiente'],title:'Pouco espaço em disco no servidor de backup.',steps:['Libere espaço no servidor ou reduza "Backups mantidos por banco" em Configurações.','Se preciso, ajuste "Reserva mínima de disco (GB)".'],where:'settings',fields:['retention_count','minimum_free_gb']},
 {m:['volume externo indisponível','cópia externa'],title:'A cópia externa não pôde ser feita.',steps:['O administrador precisa montar o destino remoto em /external no container.','Ou desmarque "Exigir cópia externa" em Configurações.'],where:'settings',fields:['external_copy']},
 {m:['worker interrompido'],title:'O executor foi reiniciado durante o backup.',steps:['Gere um novo backup de teste. Se repetir, confira os recursos do servidor (memória e disco).'],where:null,fields:[]},
 {m:['não conseguiu abrir a credencial'],title:'O sistema não conseguiu ler a senha salva do banco.',steps:['Abra a configuração do banco, digite a senha novamente e salve.','Se continuar, o administrador deve conferir o APP_KEY do .env (ele não pode ter mudado).'],where:'database',fields:['db_password']},
 {m:['mariadb não é suportado'],title:'O cliente MySQL instalado não é compatível.',steps:['O administrador precisa instalar o cliente Oracle MySQL na imagem do sistema.'],where:null,fields:[]},
];
function errorHint(message){
 if(!message)return null;const text=String(message).toLowerCase();
 return hints.find(h=>h.m.some(m=>text.includes(m)))||{title:'Não reconhecemos este erro automaticamente.',steps:['Abra "Detalhes da execução" para ler a mensagem completa.','Revise host, porta, usuário, senha e nome do banco na configuração.','Depois de corrigir, gere um novo backup de teste.'],where:'database',fields:[],generic:true};
}
function applyFix(run){
 const h=errorHint(run?.error);if(!h)return;
 if(h.where==='settings'){navigate('settings');hl.value=h.fields;focusHighlight();return;}
 const d=data.databases.find(x=>x.id===run.database_server_id);
 if(d)openDatabase(d,h);
}
function focusHighlight(){nextTick(()=>{const el=document.querySelector('.hl input, .hl select');if(el){el.scrollIntoView({block:'center',behavior:'smooth'});el.focus({preventScroll:true});}});}
function openDatabase(d=null,h=null){error.value='';fixHint.value=h;hl.value=h?.fields||[];const blank={name:'',driver:'mysql',host:'',port:3306,database_name:'',username:'',db_password:'',tls_mode:'REQUIRED',ca_file:'',consistency:'transaction',enabled:true};dbForm.value=d?{...blank,...Object.fromEntries(Object.entries(d).filter(([,v])=>v!==null)),driver:d.driver||'mysql',port:d.port??drivers[d.driver||'mysql'].port,db_password:''}:blank;modal.value='database';if(h)focusHighlight();}
function changeDriver(){const f=dbForm.value;if(!f.port||Object.values(drivers).some(x=>x.port===f.port))f.port=drivers[f.driver].port;if(f.driver!=='mysql')f.consistency='transaction';}
function openSchedule(s=null){error.value='';scheduleForm.value=s?{...s,weekdays:[...s.weekdays]}:{database_server_id:data.databases[0]?.id||'',weekdays:[2,5],start_time:'17:30',enabled:true};syncScheduleDb();modal.value='schedule';}
const scheduleDb=computed(()=>data.databases.find(d=>d.id===scheduleForm.value.database_server_id));
function syncScheduleDb(){if(scheduleDb.value&&!scheduleDb.value.enabled)scheduleForm.value.enabled=false;}
function toggleDay(n){const a=scheduleForm.value.weekdays;scheduleForm.value.weekdays=a.includes(n)?a.filter(d=>d!==n):[...a,n].sort();}
async function saveDatabase(){busy.value=true;error.value='';try{const f={...dbForm.value};const before=data.databases.find(d=>d.id===f.id);const linked=f.id?data.schedules.filter(s=>s.database_server_id===f.id).length:0;const toggled=before&&before.enabled!==f.enabled&&linked;delete f.latest_run;await api('/databases'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',f);modal.value=null;await load();notify(toggled?(f.enabled?`Banco ativado. ${linked} agendamento(s) deste banco também foram reativados.`:`Banco pausado. ${linked} agendamento(s) deste banco também foram pausados.`):'Banco salvo. Faça um teste manual para validar o acesso.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function saveSchedule(){busy.value=true;error.value='';try{const f=scheduleForm.value;if(!f.weekdays.length)throw new Error('Selecione ao menos um dia.');if(f.start_time<='17:00')throw new Error('Escolha um horário após as 17h.');await api('/schedules'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',f);modal.value=null;await load();notify('Agendamento salvo no horário de Cuiabá.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function backup(d){if(busy.value)return;busy.value=true;error.value='';try{const r=await api(`/databases/${d.id}/backup`,'POST');notify(`Backup #${r.id} adicionado à fila. O Python iniciará a execução.`);await load();navigate('history');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function saveOptions(){busy.value=true;error.value='';try{await api('/settings','PUT',options);await load(true);notify('Configurações salvas. Aplicação a partir das próximas execuções.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(async()=>{try{user.value=(await api('/me')).user;await load();}catch{}finally{booting.value=false;}timer=setInterval(()=>{if(user.value)load(true);},10000);});
onUnmounted(()=>{clearInterval(timer);clearTimeout(toastTimer);});
</script>

<template>
 <div v-if="booting" class="boot"><span class="brandmark"><ShieldCheck :size="25"/></span><p>Carregando o controle de backups…</p></div>
 <main v-else-if="!user" class="login-page"><section class="login-story"><div class="brand"><span class="brandmark"><ShieldCheck :size="24"/></span>Backup<span class="brand-light">Sistema Traz Valor</span></div><div><p class="eyebrow">PROTEÇÃO QUE FAZ PARTE DA ROTINA</p><h1>Seus dados seguros.<br>Seu trabalho<br>em movimento.</h1><p>Centralize os bancos, programe suas cópias<br>e acompanhe cada execução em um só lugar.</p><div class="login-pills"><span><LockKeyhole :size="15"/> Criptografia</span><span><CalendarClock :size="15"/> Agendamento</span></div></div><small>Feito para cuidar do que mantém seu negócio funcionando.</small></section><section class="login-box"><div class="login-symbol"><Database :size="28"/></div><p class="eyebrow">ACESSO RESTRITO</p><h2>Bem-vindo ao controle.</h2><p>Entre com o acesso criado na instalação.</p><form @submit.prevent="signIn"><label>E-mail<input v-model="login.email" type="email" required autocomplete="username" placeholder="seu@email.com"></label><label>Senha<input v-model="login.password" type="password" required autocomplete="current-password" placeholder="Sua senha de acesso"></label><div v-if="error" class="alert danger" role="alert">{{ error }}</div><button class="primary full" :disabled="busy">{{busy?'Entrando…':'Acessar painel'}}<ArrowRight :size="17"/></button></form><p class="login-note"><ShieldCheck :size="15"/> Sessão protegida · Acesso administrativo</p></section></main>
 <div v-else class="app-shell">
  <aside :class="{mobileOpen:mobileNav}"><a href="#" class="brand" @click.prevent="navigate('overview')"><span class="brandmark"><ShieldCheck :size="24"/></span><span>Backup<small>SISTEMA TRAZ VALOR</small></span></a><p class="nav-label">ESPAÇO DE TRABALHO</p><nav><button v-for="item in nav" :key="item.key" :class="{selected:page===item.key}" @click="navigate(item.key)"><component :is="item.icon" :size="18"/><span>{{item.name}}</span><ChevronRight v-if="page===item.key" :size="14"/></button></nav><div class="side-protection"><ShieldCheck :size="21"/><strong>Uma rotina mais segura.</strong><p>Backups criptografados<br>e histórico de cada cópia.</p></div><div class="account"><div class="avatar">{{user.name?.charAt(0).toUpperCase()}}</div><div><strong>{{user.name}}</strong><small>Administrador</small></div><button class="icon-button" title="Sair" @click="signOut"><LogOut :size="17"/></button></div></aside>
  <div class="main-shell"><header class="topbar"><div><button class="menu-button icon-button" title="Abrir menu" @click="mobileNav=!mobileNav"><Menu :size="20"/></button><span>Workspace</span><ChevronRight :size="13"/><strong>{{title}}</strong></div><span class="timezone"><span class="status-dot"></span>Horário de Cuiabá <span class="timezone-code">UTC −04:00</span></span></header>
  <main class="content"><div class="page-heading"><div><p class="eyebrow">DADOS PROTEGIDOS. OPERAÇÃO EM DIA.</p><h1>{{title}}</h1><p>{{page==='overview'?'Tudo o que você precisa acompanhar, em um só lugar.':page==='databases'?'Conexões organizadas, credenciais protegidas.':page==='schedules'?'Escolha quando cada banco deve ser copiado.':page==='history'?'Acompanhe o resultado e os detalhes de cada execução.':'Ajuste a retenção e os limites das próximas cópias.'}}</p></div><button v-if="page==='overview'||page==='history'" class="secondary" :disabled="loading" @click="load()"><RefreshCw :size="15" :class="{spinning:loading}"/>Atualizar</button><button v-if="page==='databases'" class="primary" @click="openDatabase()"><Plus :size="17"/>Adicionar banco</button><button v-if="page==='schedules'" class="primary" :disabled="!data.databases.length" @click="openSchedule()"><Plus :size="17"/>Novo agendamento</button></div>
   <div v-if="error && !modal" class="alert danger" role="alert"><TriangleAlert :size="18"/>{{error}}<button class="icon-button" @click="error=''" title="Fechar"><X :size="16"/></button></div>
   <div v-if="failedAge" class="alert warning"><TriangleAlert :size="18"/><div><strong>{{data.settings.worker_heartbeat?'O executor está sem contato recente.':'O executor ainda não iniciou.'}}</strong><p>Confira o serviço Python. Último contato: {{date(data.settings.worker_heartbeat)}}. Os backups dependem do executor ativo.</p></div></div>
   <template v-if="page==='overview'">
    <section class="hero"><div><span class="hero-tag"><ShieldCheck :size="14"/> SEU PLANO DE CONTINUIDADE</span><h2>Menos preocupação.<br>Mais controle dos seus dados.</h2><p>Programe os backups após as 17h e deixe a rotina<br class="desktop-break"> trabalhar por você. Os testes podem acontecer a qualquer hora.</p><button class="primary" @click="navigate('schedules')">Gerenciar agendamentos<ArrowUpRight :size="17"/></button></div><div class="hero-visual"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-server"><Database :size="66" :stroke-width="1.4"/><span class="hero-check"><ShieldCheck :size="24"/></span></div><span class="visual-label"><span class="status-dot"></span>ROTINA SOB CONTROLE</span></div></section>
    <div class="metrics"><article><div class="metric-top"><span>Bancos cadastrados</span><Database :size="18"/></div><strong>{{data.stats.databases||0}}</strong><small>Conexões centralizadas</small></article><article><div class="metric-top"><span>Rotinas ativas</span><CalendarClock :size="18"/></div><strong>{{data.stats.schedules||0}}</strong><small>Após as 17h de Cuiabá</small></article><article><div class="metric-top"><span>Backups disponíveis</span><HardDrive :size="18"/></div><strong>{{data.stats.available||0}}</strong><small>Arquivos criptografados</small></article><article><div class="metric-top"><span>Falhas em 24 horas</span><TriangleAlert :size="18"/></div><strong :class="{'text-danger':data.stats.failed}">{{data.stats.failed||0}}</strong><small>Veja os detalhes no histórico</small></article></div>
    <div class="overview-grid"><section class="card"><div class="section-heading"><div><h2>Bancos monitorados</h2><p>Um teste manual valida a conexão e o backup.</p></div><button class="text-button" @click="navigate('databases')">Ver todos<ArrowRight :size="15"/></button></div><div v-if="!data.databases.length" class="empty"><Database :size="32"/><h3>Adicione seu primeiro banco.</h3><p>Comece com o cadastro da conexão MySQL, PostgreSQL ou SQLite.</p><button class="primary" @click="openDatabase()">Adicionar banco</button></div><div v-for="d in data.databases.slice(0,5)" :key="d.id" class="database-row"><span class="db-symbol"><Database :size="20"/></span><div class="grow"><strong>{{d.name}}</strong><small>{{drivers[d.driver||'mysql'].name}} · {{d.database_name}}{{d.host?' · '+d.host:''}}</small></div><span class="badge" :class="d.latest_run?.status||(d.enabled?'ready':'expired')">{{d.latest_run?status[d.latest_run.status]:(d.enabled?'Pronto':'Pausado')}}</span><button class="small secondary" :disabled="busy||!d.enabled||['queued','running'].includes(d.latest_run?.status)" @click="backup(d)"><Play :size="13"/>Testar</button></div></section><section class="card routines-card"><div class="section-heading"><div><h2>Sua programação</h2><p>Horários de início previstos.</p></div><CalendarClock :size="20"/></div><div v-if="!activeSchedules.length" class="empty compact"><p>Nenhuma rotina ativa.</p><button class="text-button" @click="navigate('schedules')">Configurar dias e horários →</button></div><div v-for="s in activeSchedules.slice(0,3)" :key="s.id" class="routine-item"><span class="routine-clock"><Clock3 :size="17"/></span><div><strong>{{s.database_server?.name}}</strong><small>{{dayLabels(s)}}</small></div><b>{{s.start_time}}</b></div><div class="routine-note"><LockKeyhole :size="15"/><span>Agendamentos permitidos de 17:01 até 23:59.</span></div></section></div>
    <section class="trust-strip"><ShieldCheck :size="22"/><div><strong>Uma cópia só está comprovada quando pode ser restaurada.</strong><p>Os arquivos passam por validação de compressão e criptografia. Faça também uma restauração periódica em ambiente separado.</p></div></section>
   </template>
   <template v-if="page==='databases'"><section class="card"><div class="section-heading"><div><h2>Suas conexões</h2><p>As senhas nunca são devolvidas pela API.</p></div><span class="count-label">{{data.databases.length}} bancos</span></div><div class="empty" v-if="!data.databases.length"><Database :size="35"/><h3>Nenhum banco cadastrado.</h3><button class="primary" @click="openDatabase()">Adicionar banco</button></div><article v-for="d in data.databases" :key="d.id" class="connection-card"><div class="connection-top"><span class="db-symbol"><Database :size="22"/></span><div class="grow"><h3>{{d.name}}</h3><span class="badge" :class="d.enabled?'ready':'expired'">{{d.enabled?'Ativo':'Pausado'}}</span> <span class="badge ready">{{drivers[d.driver||'mysql'].name}}</span></div><button class="secondary small" @click="openDatabase(d)">Editar conexão</button></div><div class="connection-info"><div><small>SERVIDOR</small><span>{{d.driver==='sqlite'&&!d.host?'Arquivo local':(d.driver==='sqlite'?'SFTP ':'')+d.host+':'+d.port}}</span></div><div><small>{{d.driver==='sqlite'?'ARQUIVO':'BANCO'}}</small><span>{{d.database_name}}</span></div><div><small>SEGURANÇA</small><span>{{d.driver==='sqlite'?(d.host?'SSH':'Somente leitura'):d.tls_mode==='DISABLED'?'Sem TLS':d.tls_mode==='VERIFY_IDENTITY'?'TLS + certificado':'TLS obrigatório'}}</span></div></div><div v-if="d.latest_run?.status==='failed'" class="card-hint"><div class="fix-hint"><Lightbulb :size="18"/><div class="grow"><strong>{{errorHint({...d.latest_run,database_server_id:d.id}.error).title}}</strong><ol><li v-for="(step,i) in errorHint({...d.latest_run,database_server_id:d.id}.error).steps" :key="i">{{step}}</li></ol></div><button v-if="errorHint({...d.latest_run,database_server_id:d.id}.error).where" class="secondary small" @click="applyFix({...d.latest_run,database_server_id:d.id})"><Wrench :size="14"/>{{errorHint({...d.latest_run,database_server_id:d.id}.error).where==='settings'?'Abrir configurações':'Corrigir configuração do banco'}}</button></div></div><div class="connection-bottom"><small>Última execução: {{d.latest_run?status[d.latest_run.status]+' · '+date(d.latest_run.created_at):'Ainda não executado'}}</small><button class="primary small" :disabled="busy||!d.enabled||['queued','running'].includes(d.latest_run?.status)" @click="backup(d)"><Play :size="13"/>Gerar backup de teste</button></div></article></section></template>
   <template v-if="page==='schedules'"><div class="alert info"><Clock3 :size="20"/><div><strong>Você escolhe os dias. O sistema cuida da rotina.</strong><p>Horários em America/Cuiaba, sempre após as 17h. Os bancos são processados um por vez; o início pode atrasar se houver outro backup em execução.</p></div></div><section class="schedule-grid"><article v-for="s in data.schedules" :key="s.id" class="card schedule-card"><div class="section-heading"><span class="schedule-icon"><CalendarClock :size="22"/></span><span class="badge" :class="s.enabled&&s.database_server?.enabled?'ready':'expired'">{{s.enabled&&s.database_server?.enabled?'Ativo':'Pausado'}}</span></div><h2>{{s.database_server?.name}}</h2><p v-if="!s.database_server?.enabled" class="paused-note"><TriangleAlert :size="14"/>Pausado porque o banco está inativo. Ative o banco em <a href="#" @click.prevent="navigate('databases')">Bancos de dados</a>.</p><p class="schedule-time">{{s.start_time}}<small>HORÁRIO DE CUIABÁ</small></p><div class="week-display"><span v-for="d in days" :key="d.n" :class="{chosen:s.weekdays.includes(d.n)}">{{d.s}}</span></div><button class="secondary full" @click="openSchedule(s)">Editar agendamento<ArrowUpRight :size="15"/></button></article><button class="add-schedule" :disabled="!data.databases.length" @click="openSchedule()"><Plus :size="30"/><strong>Uma nova rotina</strong><span>Defina banco, dias e horário.</span></button></section></template>
   <template v-if="page==='history'"><section class="card history-card"><div class="section-heading"><div><h2>Execuções recentes</h2><p>Últimas 100 execuções. Atualização automática a cada 10 segundos.</p></div><label class="search-field"><Search :size="16"/><input v-model="search" aria-label="Pesquisar histórico" placeholder="Buscar banco ou status"></label></div><div class="table-scroll"><table><thead><tr><th>Banco / execução</th><th>Solicitado em</th><th>Resultado</th><th>Arquivo</th><th></th></tr></thead><tbody><template v-for="r in filteredRuns" :key="r.id"><tr><td><strong>{{r.database_server?.name}}</strong><small>#{{r.id}} · {{r.source==='manual'?'Teste manual':'Agendamento'}}</small></td><td>{{date(r.created_at)}}<small>Fim: {{date(r.finished_at)}}</small></td><td><span class="badge" :class="r.status"><span class="status-dot"></span>{{status[r.status]}}</span></td><td>{{bytes(r.size_bytes)}}<small v-if="r.status==='success'">Download em ZIP (.sql)</small></td><td><a v-if="r.status==='success'" class="download-link" :href="`/api/runs/${r.id}/download`" title="Baixar backup em ZIP (.sql)"><Download :size="17"/></a></td></tr><tr v-if="r.status==='failed'" class="hint-row"><td colspan="5"><div class="fix-hint"><Lightbulb :size="18"/><div class="grow"><strong>{{errorHint(r.error).title}}</strong><ol><li v-for="(step,i) in errorHint(r.error).steps" :key="i">{{step}}</li></ol></div><button v-if="errorHint(r.error).where" class="secondary small" @click="applyFix(r)"><Wrench :size="14"/>{{errorHint(r.error).where==='settings'?'Abrir configurações':'Corrigir configuração do banco'}}</button></div></td></tr><tr class="detail-row"><td colspan="5"><details><summary>Detalhes da execução #{{r.id}}</summary><div class="run-details"><p v-if="r.error" class="text-danger">{{r.error}}</p><p>Início: {{date(r.started_at)}} · Fim: {{date(r.finished_at)}}</p><p v-if="r.sha256">SHA-256: <code>{{r.sha256}}</code></p><pre v-if="r.details">{{JSON.stringify(r.details,null,2)}}</pre></div></details></td></tr></template><tr v-if="!filteredRuns.length"><td colspan="5"><div class="empty"><History :size="32"/><h3>Nenhuma execução encontrada.</h3><p>Gere um backup de teste para começar.</p></div></td></tr></tbody></table></div></section></template>
   <template v-if="page==='settings'"><div class="settings-grid"><section class="card"><div class="section-heading"><div><h2>Retenção e execução</h2><p>Aplicados às próximas execuções do worker.</p></div><Settings :size="20"/></div><form @submit.prevent="saveOptions"><label :class="{hl:hl.includes('retention_count')}">Backups mantidos por banco<input v-model.number="options.retention_count" type="number" min="1" max="104" required><small>Somente backups concluídos entram na retenção. O histórico permanece.</small></label><div class="form-grid"><label :class="{hl:hl.includes('timeout_minutes')}">Tempo máximo do dump (minutos)<input v-model.number="options.timeout_minutes" type="number" min="1" max="1440" required></label><label :class="{hl:hl.includes('minimum_free_gb')}">Reserva mínima de disco (GB)<input v-model.number="options.minimum_free_gb" type="number" min="1" max="10000" required></label></div><label class="toggle-label" :class="{hl:hl.includes('external_copy')}"><input v-model="options.external_copy" type="checkbox"><span><strong>Exigir cópia externa</strong><small>O administrador precisa montar o destino remoto em /external no container.</small></span></label><div class="alert warning small-alert">Se a cópia externa falhar, a execução será marcada como falha, o arquivo local será preservado e a retenção não será aplicada.</div><button class="primary" :disabled="busy">Salvar configurações<ArrowRight :size="16"/></button></form></section><div><section class="card settings-note"><span class="db-symbol"><ShieldCheck :size="24"/></span><h2>As chaves são essenciais.</h2><p>Guarde uma cópia segura de <code>/data/app.key</code> e <code>/data/keys/backup.key</code> fora deste servidor.</p><p>Sem a chave de backup, os arquivos criptografados não podem ser recuperados.</p></section><section class="card"><h2>Execução em segundo plano</h2><p class="settings-detail">O serviço Python precisa estar ativo, mesmo que o painel esteja fechado.</p><div class="health-line"><span class="status-dot" :class="{offline:failedAge}"></span>{{failedAge?'Sem contato recente':'Executor conectado'}}</div><small>Último contato: {{date(data.settings.worker_heartbeat)}}</small></section></div></div></template>
   <footer><span><ShieldCheck :size="13"/>Backup Manager</span><span>Laravel + Python + Vue.js <span class="footer-dot">·</span> Horário de Cuiabá</span></footer>
  </main></div>
 </div>
 <div v-if="toast" class="toast" role="status"><CircleCheck :size="19"/><span>{{toast}}</span><button class="icon-button" @click="toast=''" title="Fechar"><X :size="16"/></button></div>
 <div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal=null)"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal==='database'?'Configurar banco':'Configurar agendamento'"><div class="modal-heading"><div><p class="eyebrow">{{modal==='database'?'CONEXÃO '+drivers[dbForm.driver||'mysql'].name.toUpperCase():'SUA ROTINA DE BACKUP'}}</p><h2>{{modal==='database'?(dbForm.id?'Editar banco':'Adicionar banco'):(scheduleForm.id?'Editar agendamento':'Novo agendamento')}}</h2></div><button class="icon-button" :disabled="busy" @click="modal=null" title="Fechar"><X :size="22"/></button></div><div v-if="error" class="alert danger" role="alert">{{error}}</div><div v-if="modal==='database'&&fixHint" class="fix-hint in-modal"><Lightbulb :size="18"/><div><strong>{{fixHint.title}}</strong><ol><li v-for="(step,i) in fixHint.steps" :key="i">{{step}}</li></ol><small v-if="hl.length">Os campos a revisar estão destacados em amarelo.</small></div></div>
  <form v-if="modal==='database'" @submit.prevent="saveDatabase"><div class="form-grid"><label :class="{hl:hl.includes('name')}">Nome do banco<input v-model="dbForm.name" required maxlength="120" placeholder="Ex.: Traz Valor"></label><label>Tipo de banco<select v-model="dbForm.driver" required @change="changeDriver"><option value="mysql">MySQL</option><option value="pgsql">PostgreSQL</option><option value="sqlite">SQLite</option></select></label></div><div class="host-grid"><label :class="{hl:hl.includes('host')}">{{dbForm.driver==='sqlite'?'Host SSH (vazio = arquivo local)':'Host '+drivers[dbForm.driver].name}}<input v-model="dbForm.host" :required="dbForm.driver!=='sqlite'" maxlength="253" :placeholder="dbForm.driver==='sqlite'?'servidor.exemplo.com':dbForm.driver==='pgsql'?'postgres.exemplo.com':'mysql.exemplo.com'"></label><label :class="{hl:hl.includes('port')}">Porta<input v-model.number="dbForm.port" type="number" min="1" max="65535" :required="dbForm.driver!=='sqlite'||!!dbForm.host"></label></div><div class="form-grid"><label :class="{hl:hl.includes('database_name')}">{{dbForm.driver==='sqlite'?(dbForm.host?'Caminho do arquivo no servidor':'Arquivo na pasta sqlite/'):'Banco de dados'}}<input v-model="dbForm.database_name" required :maxlength="dbForm.driver==='sqlite'?255:64" :placeholder="dbForm.driver==='sqlite'?(dbForm.host?'/home/usuario/app/database.sqlite':'sistema.sqlite'):''"></label><label :class="{hl:hl.includes('username')}">Usuário {{dbForm.driver==='sqlite'?'SSH':drivers[dbForm.driver].name}}<input v-model="dbForm.username" :required="dbForm.driver!=='sqlite'||!!dbForm.host" maxlength="128" autocomplete="off"></label></div><label :class="{hl:hl.includes('db_password')}">Senha {{dbForm.driver==='sqlite'?'SSH':drivers[dbForm.driver].name}}<input v-model="dbForm.db_password" type="password" :required="!dbForm.id&&(dbForm.driver!=='sqlite'||!!dbForm.host)" autocomplete="new-password" :placeholder="dbForm.id?'Deixe vazio para manter a senha atual':'Informe a senha'"></label><div class="form-grid"><label :class="{hl:hl.includes('tls_mode')}">Conexão TLS<select v-model="dbForm.tls_mode"><option value="REQUIRED">Exigir TLS</option><option value="VERIFY_IDENTITY">TLS + validar identidade</option><option value="DISABLED">Sem TLS / túnel externo</option></select></label><label :class="{hl:hl.includes('ca_file')}">Arquivo CA (opcional)<input v-model="dbForm.ca_file" placeholder="ca.pem, dentro de /certs"></label></div><label :class="{hl:hl.includes('consistency')}">Consistência do backup<select v-model="dbForm.consistency"><option value="transaction">{{dbForm.driver==='mysql'?'Transação InnoDB':'Snapshot consistente'}}</option><option v-if="dbForm.driver==='mysql'" value="tables">Bloqueio das tabelas do banco (MyISAM)</option><option v-if="dbForm.driver==='mysql'" value="locked">Bloqueio global — legado</option></select></label><div v-if="dbForm.driver==='mysql'&&dbForm.consistency==='locked'" class="alert warning small-alert">O bloqueio global pode interromper escritas em toda a instância durante o backup. Exige privilégios e janela de manutenção.</div><div v-else-if="dbForm.driver==='mysql'&&dbForm.consistency==='tables'" class="alert warning small-alert">Indicado para bancos com tabelas MyISAM em hospedagem compartilhada. As gravações neste banco ficam bloqueadas durante a cópia (leituras continuam). Agende fora do horário de uso.</div><p v-else-if="dbForm.driver==='mysql'" class="field-hint">MyISAM e outros motores não transacionais são recusados neste modo. Evite migrações de estrutura durante o backup.</p><p v-else-if="dbForm.driver==='pgsql'" class="field-hint">O pg_dump usa um snapshot consistente, sem bloquear escritas. A versão do cliente precisa ser igual ou superior à do servidor.</p><p v-else class="field-hint">Com host preenchido, o arquivo é baixado por SFTP/SSH (porta 22) e o backup é gerado da cópia. A chave SSH do servidor é registrada no primeiro acesso. TLS e CA não se aplicam ao SSH. Sem host, o arquivo é lido da pasta <code>sqlite</code> do projeto. Prefira horários sem gravação no banco.</p><label class="toggle-label"><input type="checkbox" v-model="dbForm.enabled"><span>Banco ativo<small v-if="dbForm.id&&data.schedules.some(s=>s.database_server_id===dbForm.id)">Os agendamentos deste banco acompanham este status: pausar o banco pausa os agendamentos, ativar o banco reativa.</small></span></label><div class="modal-actions"><button type="button" class="secondary" :disabled="busy" @click="modal=null">Cancelar</button><button class="primary" :disabled="busy">{{busy?'Salvando…':'Salvar banco'}}<ArrowRight :size="16"/></button></div></form>
  <form v-else @submit.prevent="saveSchedule"><label>Banco<select v-model.number="scheduleForm.database_server_id" required @change="syncScheduleDb"><option v-for="d in data.databases" :key="d.id" :value="d.id">{{d.name}}{{d.enabled?'':' (inativo)'}}</option></select></label><div v-if="scheduleDb&&!scheduleDb.enabled" class="alert warning small-alert"><TriangleAlert :size="17"/><span>O banco <strong>{{scheduleDb.name}}</strong> está inativo, então este agendamento fica pausado. Para ativar, abra <a href="#" @click.prevent="modal=null;navigate('databases')">Bancos de dados</a>, clique em "Editar conexão" e marque "Banco ativo".</span></div><fieldset><legend>Dias da semana</legend><div class="day-picker"><button v-for="d in days" :key="d.n" type="button" :aria-pressed="scheduleForm.weekdays.includes(d.n)" :class="{chosen:scheduleForm.weekdays.includes(d.n)}" @click="toggleDay(d.n)">{{d.s}}</button></div></fieldset><label>Horário de início<input v-model="scheduleForm.start_time" type="time" min="17:01" max="23:59" required></label><div class="alert info small-alert"><Clock3 :size="17"/><span>Após as 17h, no horário de Cuiabá. Testes manuais podem rodar a qualquer hora.</span></div><label class="toggle-label"><input type="checkbox" v-model="scheduleForm.enabled" :disabled="scheduleDb&&!scheduleDb.enabled"><span>Agendamento ativo<small v-if="scheduleDb&&!scheduleDb.enabled">Disponível quando o banco estiver ativo.</small></span></label><div class="modal-actions"><button type="button" class="secondary" :disabled="busy" @click="modal=null">Cancelar</button><button class="primary" :disabled="busy">{{busy?'Salvando…':'Salvar agendamento'}}<ArrowRight :size="16"/></button></div></form>
 </section></div>
</template>
